def distance(left, right):
    """Return Levenshtein distance, stopping once the result exceeds 2."""
    left, right = str(left).lower(), str(right).lower()
    if len(left) > len(right):
        left, right = right, left
    if len(right) - len(left) > 2:
        return 3
    prev = list(range(len(left) + 1))
    for j, rc in enumerate(right, 1):
        cur = [j]
        for i, lc in enumerate(left, 1):
            cur.append(min(cur[-1] + 1, prev[i] + 1,
                           prev[i - 1] + (lc != rc)))
        if min(cur) > 2:
            return 3
        prev = cur
    return prev[-1]


def suggest(query, candidates):
    """Return the closest sufficiently similar candidate, or None.

    Task suggestions tolerate up to two edits but avoid guessing for very
    short queries, where the same distance is not informative.
    """
    query = str(query)
    if len(query) < 3:
        return None
    ranked = [(distance(query, candidate), str(candidate)) for candidate in candidates]
    ranked = [(d, name) for d, name in ranked if d <= 2]
    if not ranked:
        return None
    ranked.sort(key=lambda pair: (pair[0], pair[1]))
    return ranked[0][1]
